"""Package the optional x86 menu plugin with its required matched Bridge identity."""
from pathlib import Path
import hashlib
import json
import shutil
import subprocess
import zipfile
from package_release import machine

ROOT = Path(__file__).resolve().parents[1]
receipt = json.loads((ROOT / 'work/ipc-full-build.json').read_text())
binary = ROOT / '.deps/l4n-plugin/L4D2BridgePlugin.dll'
if machine(binary) != 0x14c or b'common-settings-3' not in binary.read_bytes():
    raise RuntimeError('Expected x86 common-settings-3 plugin')
digest = hashlib.sha256(binary.read_bytes()).hexdigest()
payload = 'bin/neko/plugins/L4D2BridgePlugin.dll'
out = ROOT / 'dist/l4n-config-menu'
out.mkdir(parents=True, exist_ok=False)
(out / payload).parent.mkdir(parents=True)
shutil.copy2(binary, out / payload)
info = dict(kind='optional-l4n-plugin', plugin_version='common-settings-3',
            source_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(), required_bridge_build=receipt['build_id'],
            build_type='Release', language_default='English', language_persisted=False,
            config_only=['client.ipcBatchSize', 'client.vbibMappedShadow'],
            game_restart_required=True, gameplay_validated=False, files={payload: digest})
(out / 'BUILD-INFO.json').write_text(json.dumps(info, indent=2) + '\n')
(out / 'SHA256.json').write_text(json.dumps(info['files'], indent=2) + '\n')
shutil.copy2(ROOT / 'docs/L4N-CONFIG-MENU.md', out / 'INSTALL.zh-CN.md')
for name in ('LICENSE', 'THIRD_PARTY.md'):
    shutil.copy2(ROOT / name, out / name)
name = 'l4d2-bridge-l4n-config-menu-' + receipt['build_id'].split('+')[1] + '.zip'
package = ROOT / 'dist' / name
with zipfile.ZipFile(package, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
    for path in sorted(out.rglob('*')):
        if path.is_file():
            archive.write(path, path.relative_to(out))
checksum = hashlib.sha256(package.read_bytes()).hexdigest()
(ROOT / 'dist/L4N-SHA256SUMS.txt').write_text(checksum + '  ' + name + '\n')
print(name, checksum)
